  <script>
    const orderDates = [
      { gregorian: "2025-06-18T12:00:00+03:00", hijri: "12 ذو الحجة 1446" },
      { gregorian: "2025-05-02T12:00:00+03:00", hijri: "4 شوال 1446" },
      { gregorian: "2025-04-20T12:00:00+03:00", hijri: "21 رمضان 1446" },
      { gregorian: "2025-03-08T12:00:00+03:00", hijri: "9 رمضان 1446" }
    ];

    const cards = [...document.querySelectorAll(".order-card")];

    cards.forEach((card, index) => {
      const date = new Date(orderDates[index].gregorian);
      const gregorian = new Intl.DateTimeFormat("ar-SA-u-ca-gregory-nu-latn", {
        day: "numeric",
        month: "long",
        year: "numeric",
        timeZone: "Asia/Riyadh"
      }).format(date);

      card.querySelector(".gregorian-date").textContent = gregorian;
      card.querySelector(".hijri-date").textContent = orderDates[index].hijri;

      const button = card.querySelector(".details-button");
      const details = card.querySelector(".order-details");

      button.addEventListener("click", () => {
        const isOpen = details.classList.toggle("open");
        button.setAttribute("aria-expanded", String(isOpen));
      });
    });

    const filterButtons = [...document.querySelectorAll(".filter")];
    const emptyState = document.getElementById("empty-state");

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const selectedFilter = button.dataset.filter;

        filterButtons.forEach((item) => {
          item.setAttribute("aria-selected", String(item === button));
        });

        let visibleCount = 0;

        cards.forEach((card) => {
          const shouldShow = selectedFilter === "all" || card.dataset.status === selectedFilter;
          card.hidden = !shouldShow;
          if (shouldShow) visibleCount++;
        });

        emptyState.classList.toggle("visible", visibleCount === 0);
      });
    });
  </script>
